import numpy as np

def calculate_R(N):
    """Calculates R(N) = sum_{a=1}^N sum_{b=1}^N {ab / (N+1)}"""
    R_sum = 0.0
    divisor = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # Calculate the fractional part: {x} = x - floor(x)
            fractional_part = (a * b / divisor) - np.floor(a * b / divisor)
            R_sum += fractional_part
    return R_sum

def calculate_T(N):
    """Calculates the target value T(N) = (N^2 - 1) / 2"""
    return (N**2 - 1) / 2.0

results = {}
for N in range(1, 11):
    R_N = calculate_R(N)
    T_N = calculate_T(N)
    Difference = R_N - T_N

    results[N] = {
        'R': R_N,
        'T': T_N,
        'D': Difference
    }

print("N | R(N) | T(N) | D(N)")
print("--------------------------------")
for N in range(1, 11):
    res = results[N]
    # Using precision for output clarity
    print(f"{N:2} | {res['R']:.4f} | {res['T']:.4f} | {res['D']:.4f}")

